#!/usr/bin/env bash
# Generated by Claude Opus 4.8 (claude.ai/code) - 2026-11-13
# Installer for the backup sequencer (Linux, system-wide). Requires PowerShell 7 (pwsh).

set -euo pipefail

REPO_SLUG="sandrock/backup-sequencer"
REF="${BSEQ_REF:-main}"

# Target locations (override for testing or non-standard layouts).
CODE_DIR="${BSEQ_CODE_DIR:-/opt/backup-sequencer}"
BIN_DIR="${BSEQ_BIN_DIR:-/usr/local/bin}"
CONFIG_DIR="${BSEQ_CONFIG_DIR:-/etc/backup-sequencer}"
VAR_DIR="${BSEQ_VAR_DIR:-/var/lib/backup-sequencer}"
SPOOL_DIR="${BSEQ_SPOOL_DIR:-/var/spool/backup-sequencer}"
SYSTEMD_DIR="${BSEQ_SYSTEMD_DIR:-/etc/systemd/system}"

CMD_NAME="bseq"

ASSUME_YES=0
NO_SYSTEMD=0
FROM_DIR=""

usage() {
    cat <<'EOF'
Install the backup sequencer system-wide (Linux).

Usage: install.sh [options]

Options:
  --from <dir>    Install from a local checkout instead of downloading.
  --ref <ref>     Branch or tag to download (default: main). Ignored with --from.
  --no-systemd    Do not install the systemd .service/.timer units.
  -y, --yes       Do not prompt for confirmation.
  -h, --help      Show this help and exit.

By default the systemd units are installed (disabled) when systemd is present;
existing units are never overwritten. The command installed is "bseq".

Locations (override via environment):
  BSEQ_CODE_DIR    code         (default /opt/backup-sequencer)
  BSEQ_BIN_DIR     CLI wrapper  (default /usr/local/bin)
  BSEQ_CONFIG_DIR  config       (default /etc/backup-sequencer)
  BSEQ_VAR_DIR     state        (default /var/lib/backup-sequencer)
  BSEQ_SPOOL_DIR   spool        (default /var/spool/backup-sequencer)
  BSEQ_SYSTEMD_DIR unit dir     (default /etc/systemd/system)

Requires PowerShell 7 (pwsh) on PATH. Run as root for the default locations.
EOF
}

die() { echo "error: $*" >&2; exit 1; }
systemd_present() { command -v systemctl >/dev/null 2>&1 || [ -d /run/systemd/system ]; }

while [ $# -gt 0 ]; do
    case "$1" in
        --from) FROM_DIR="${2:-}"; shift 2 ;;
        --ref) REF="${2:-}"; shift 2 ;;
        --no-systemd) NO_SYSTEMD=1; shift ;;
        -y|--yes) ASSUME_YES=1; shift ;;
        -h|--help) usage; exit 0 ;;
        *) die "unknown option: $1 (see --help)" ;;
    esac
done

# --- prerequisite: pwsh ---
command -v pwsh >/dev/null 2>&1 || die "PowerShell 7 (pwsh) not found on PATH. Install it first: https://learn.microsoft.com/powershell/scripting/install/installing-powershell-on-linux"
PWSH="$(command -v pwsh)"

# --- should we install the systemd units? default yes when systemd is present ---
INSTALL_SYSTEMD=0
if [ "$NO_SYSTEMD" != 1 ] && systemd_present; then INSTALL_SYSTEMD=1; fi

# --- obtain the source tree ---
WORK=""
cleanup() { [ -n "$WORK" ] && rm -rf "$WORK"; }
trap cleanup EXIT

if [ -n "$FROM_DIR" ]; then
    [ -f "$FROM_DIR/src/sequencer.ps1" ] || die "--from '$FROM_DIR' is not a backup-sequencer checkout (no src/sequencer.ps1)"
    SRC="$FROM_DIR"
    SRC_DESC="local checkout $FROM_DIR"
else
    command -v curl >/dev/null 2>&1 || die "curl not found (needed to download; or use --from <dir>)"
    command -v tar  >/dev/null 2>&1 || die "tar not found"
    WORK="$(mktemp -d)"
    url="https://github.com/${REPO_SLUG}/archive/refs/heads/${REF}.tar.gz"
    echo "Downloading ${url} ..."
    curl -fsSL "$url" | tar -xz -C "$WORK" || die "download/extract failed for ref '$REF'"
    SRC="$(find "$WORK" -maxdepth 1 -type d -name 'backup-sequencer-*' | head -n1)"
    { [ -n "$SRC" ] && [ -f "$SRC/src/sequencer.ps1" ]; } || die "downloaded tree missing src/sequencer.ps1"
    SRC_DESC="${REPO_SLUG}@${REF}"
fi

# guard: never wipe a tree onto itself
SRC_ABS="$(cd "$SRC" && pwd)"
[ "$SRC_ABS" = "$CODE_DIR" ] && die "source and install dir are the same ($CODE_DIR)"

# --- summary + confirm ---
cat <<EOF

About to install backup-sequencer:
  source   : $SRC_DESC
  pwsh     : $PWSH
  code     -> $CODE_DIR
  command  -> $BIN_DIR/$CMD_NAME
  config   -> $CONFIG_DIR   (config.sample.json; an existing config.json is kept)
  state    -> $VAR_DIR
  spool    -> $SPOOL_DIR
  systemd  : $([ "$INSTALL_SYSTEMD" = 1 ] && echo "units -> $SYSTEMD_DIR (disabled; existing kept)" || echo "skipped")
EOF
if [ "$ASSUME_YES" != 1 ]; then
    if [ -t 0 ]; then
        printf 'Continue? [Y/n] '; read -r reply || true
    elif [ -e /dev/tty ]; then
        printf 'Continue? [Y/n] ' > /dev/tty; read -r reply < /dev/tty || true
    else
        die "non-interactive; re-run with --yes to proceed"
    fi
    case "${reply:-}" in [nN]*) echo "aborted."; exit 1 ;; esac
fi

ensure_dir() { mkdir -p "$1" 2>/dev/null || die "cannot create $1 (need root? re-run with sudo)"; }

# --- install the code tree (config/var/spool are never touched here) ---
ensure_dir "$(dirname "$CODE_DIR")"
[ -d "$CODE_DIR" ] && rm -rf "$CODE_DIR"
ensure_dir "$CODE_DIR"
for item in src help packages config.sample.json README.md LICENSE; do
    [ -e "$SRC/$item" ] && cp -R "$SRC/$item" "$CODE_DIR/"
done

# --- CLI wrapper: a thin bash shim that runs the sequencer under pwsh ---
ensure_dir "$BIN_DIR"
wrapper="$BIN_DIR/$CMD_NAME"
cat > "$wrapper" <<EOF
#!/usr/bin/env bash
# backup-sequencer CLI wrapper (installed by install.sh).
exec "$PWSH" -NoProfile -SettingsFile "$CODE_DIR/packages/powershell.config.json" "$CODE_DIR/src/sequencer.ps1" "\$@"
EOF
chmod +x "$wrapper"

# --- config / state / spool ---
ensure_dir "$CONFIG_DIR"
ensure_dir "$VAR_DIR"
ensure_dir "$SPOOL_DIR"
cp "$SRC/config.sample.json" "$CONFIG_DIR/config.sample.json"
[ -f "$CONFIG_DIR/config.json" ] || echo "note: no $CONFIG_DIR/config.json yet — copy config.sample.json to config.json and edit it."

# --- systemd units: on by default, path-adjusted, never clobbering, never enabled ---
if [ "$INSTALL_SYSTEMD" = 1 ]; then
    ensure_dir "$SYSTEMD_DIR"
    if [ -f "$SYSTEMD_DIR/backup-sequencer.service" ]; then
        echo "kept existing $SYSTEMD_DIR/backup-sequencer.service"
    else
        sed "s#/opt/backup-sequencer#${CODE_DIR}#g" "$SRC/packages/systemd/backup-sequencer.service" > "$SYSTEMD_DIR/backup-sequencer.service"
    fi
    if [ -f "$SYSTEMD_DIR/backup-sequencer.timer" ]; then
        echo "kept existing $SYSTEMD_DIR/backup-sequencer.timer"
    else
        cp "$SRC/packages/systemd/backup-sequencer.timer" "$SYSTEMD_DIR/backup-sequencer.timer"
    fi
    echo "systemd units in $SYSTEMD_DIR (disabled). Enable the nightly run with:"
    echo "  sudo systemctl daemon-reload"
    echo "  sudo systemctl enable --now backup-sequencer.timer"
fi

echo
echo "Done. Try:  $CMD_NAME plan"
